create schema if not exists adsn;
revoke all on schema adsn from public;
do $$ begin if not exists(select from pg_roles where rolname='adsn_app') then create role adsn_app login; end if; end $$;
create table adsn.products(id uuid primary key default gen_random_uuid(),name text not null check(length(trim(name)) between 1 and 160),normalized_name text not null,brand text not null default '',category text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(normalized_name,brand));
create table adsn.pallets(id uuid primary key default gen_random_uuid(),pallet_identifier text not null check(length(trim(pallet_identifier)) between 1 and 160),status text not null check(status in('DRAFT','ACTIVE','EMPTY','ARCHIVED')),version integer not null default 1,created_at timestamptz not null default now(),activated_at timestamptz,updated_at timestamptz not null default now(),closed_at timestamptz);
create unique index pallet_live_name on adsn.pallets(lower(regexp_replace(trim(pallet_identifier),'\s+',' ','g'))) where status in('DRAFT','ACTIVE');
create index pallet_status_updated on adsn.pallets(status,updated_at desc);
create table adsn.pallet_items(id uuid primary key default gen_random_uuid(),pallet_id uuid not null references adsn.pallets(id),product_id uuid not null references adsn.products(id),quantity_remaining integer not null check(quantity_remaining between 0 and 1000000),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(pallet_id,product_id));
create index items_product on adsn.pallet_items(product_id);
create table adsn.requests(idempotency_key uuid primary key,payload_hash text not null,response jsonb not null,created_at timestamptz not null default now());
create table adsn.inventory_movements(id uuid primary key default gen_random_uuid(),idempotency_key uuid not null references adsn.requests(idempotency_key) deferrable initially deferred,movement_group_id uuid not null,action_type text not null check(action_type in('PALLET_CREATED','PALLET_ACTIVATED','STOCK_ADDED','STOCK_REPLENISHED','STOCK_ADJUSTED','STOCK_TRANSFERRED','PALLET_CLOSED','PALLET_EDITED')),product_id uuid references adsn.products(id),source_pallet_id uuid references adsn.pallets(id),destination_pallet_id uuid references adsn.pallets(id),quantity integer not null,quantity_before integer check(quantity_before>=0),quantity_after integer check(quantity_after>=0),notes text check(length(notes)<=300),created_at timestamptz not null default now(),check(action_type='STOCK_ADJUSTED' or quantity>=0));
create index movements_time on adsn.inventory_movements(created_at desc);
create index movements_source on adsn.inventory_movements(source_pallet_id);
create index movements_destination on adsn.inventory_movements(destination_pallet_id);
create index movements_product on adsn.inventory_movements(product_id);
create table adsn.credential(id integer primary key check(id=1),password_hash text not null,rotated_at timestamptz not null default now());
create table adsn.sessions(id uuid primary key default gen_random_uuid(),token_hash text not null unique,expires_at timestamptz not null,created_at timestamptz not null default now());
create index sessions_expiry on adsn.sessions(expires_at);
create table adsn.login_control(id integer primary key check(id=1),failures integer not null default 0,window_started timestamptz not null default now(),locked_until timestamptz);
insert into adsn.login_control(id) values(1);
create function adsn.prevent_history_change() returns trigger language plpgsql set search_path='' as $$ begin raise exception 'Inventory history is immutable'; end $$;
create trigger immutable_history before update or delete on adsn.inventory_movements for each row execute function adsn.prevent_history_change();
revoke all on all tables in schema adsn from public;
revoke all on all functions in schema adsn from public;
grant usage on schema adsn to adsn_app;
grant select,insert,update on adsn.products,adsn.pallets,adsn.pallet_items to adsn_app;
grant delete on adsn.pallet_items to adsn_app;
grant select,insert on adsn.inventory_movements,adsn.requests to adsn_app;
grant select on adsn.credential to adsn_app;
grant select,insert,delete on adsn.sessions to adsn_app;
grant select,update on adsn.login_control to adsn_app;
-- Private schema is never exposed via PostgREST. RLS is additional defense in depth.
do $$ declare t text; begin foreach t in array array['products','pallets','pallet_items','requests','inventory_movements','credential','sessions','login_control'] loop execute format('alter table adsn.%I enable row level security',t); execute format('create policy server_access on adsn.%I to adsn_app using (true) with check (true)',t); end loop; end $$;
